import{_ as o,C as a,c as r,o as l,aj as d,G as t,w as s}from"./chunks/framework.Bfdr4H5E.js";const v=JSON.parse('{"title":"Trading Plan","description":"","frontmatter":{"outline":"deep","prev":{"text":"Trading Platform Setup","link":"/trading-with-pav/trading-platform-setup"},"next":{"text":"Trading Plan Template","link":"/trading-with-pav/trading-plan-template"}},"headers":[],"relativePath":"trading-with-pav/trading-plan.md","filePath":"trading-with-pav/trading-plan.md"}'),h={name:"trading-with-pav/trading-plan.md"};function p(u,e,c,m,g,y){const n=a("GraphComment"),i=a("ClientOnly");return l(),r("div",null,[e[0]||(e[0]=d('<h1 id="trading-plan" tabindex="-1">Trading Plan <a class="header-anchor" href="#trading-plan" aria-label="Permalink to &quot;Trading Plan&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Table of Contents</p><nav class="table-of-contents"><ul><li><a href="#trading-plan-1">Trading Plan</a><ul><li><a href="#what-is-a-trading-plan">What is a Trading Plan?</a></li><li><a href="#creating-your-trading-plan">Creating Your Trading Plan</a></li><li><a href="#living-document-vs-static-document">Living Document vs Static Document</a></li><li><a href="#detailed-vs-simple">Detailed vs Simple</a></li><li><a href="#the-trading-plan-template">The Trading Plan Template</a></li></ul></li><li><a href="#comments">Comments</a></li></ul></nav></div><h2 id="trading-plan-1" tabindex="-1">Trading Plan <a class="header-anchor" href="#trading-plan-1" aria-label="Permalink to &quot;Trading Plan&quot;">​</a></h2><h3 id="what-is-a-trading-plan" tabindex="-1">What is a Trading Plan? <a class="header-anchor" href="#what-is-a-trading-plan" aria-label="Permalink to &quot;What is a Trading Plan?&quot;">​</a></h3><p>Your Trading Plan is the principal document that guides all aspects of your trading business. If someone else wished to know how you run your trading business, this is the first place they should look. All other documents, plans or procedures are secondary to, and should be referenced by, the Trading Plan.</p><h3 id="creating-your-trading-plan" tabindex="-1">Creating Your Trading Plan <a class="header-anchor" href="#creating-your-trading-plan" aria-label="Permalink to &quot;Creating Your Trading Plan&quot;">​</a></h3><p>In many respects, this whole YSTC Trading with Price Action Volume eight-volume series comprises a part of your Trading Plan.</p><p>However this is not enough to allow you to start trading the markets.</p><p>Everyone’s interpretation of the strategy will be unique. And as you work through the trader development stages outlined in <a href="/sk/trading-with-pav/the-development-stages/">article 94</a>, you will very likely adapt and modify the strategy to suit your own psychology and trading needs.</p><p>Plus, everyone is different with respect to their personal and financial situation, their risk tolerance, and many other personal factors which need to be considered and documented.</p><p>You must therefore create your OWN trading plan.</p><p>The following articles will provide a general template and explanatory notes. Read through the article now; complete the remainder of Module 6 : YOUR TRADING BUSINESS, Module 7 : TRADER DEVELOPMENT, Module 8 : CONCLUSION; and then come back to this section to draft your own trading plan using your word processor. The greater the effort you put into creation of your plan, the greater the potential rewards in your trading business.</p><p>I would love to be able to provide a completed plan. Unfortunately that wouldn’t work. Your plan must be your own. So feel free to vary the template however you see fit. Remove sections which do not apply to your circumstances. And add additional information as required.</p><h3 id="living-document-vs-static-document" tabindex="-1">Living Document vs Static Document <a class="header-anchor" href="#living-document-vs-static-document" aria-label="Permalink to &quot;Living Document vs Static Document&quot;">​</a></h3><p>Your trading plan should be viewed as a living document. It will grow and evolve, as your level of development grows and evolves. As such, I recommend you implement a regular review of the document to ensure it remains relevant. Prior to becoming consistently profitable, I recommend this review be conducted monthly. Beyond that stage, extend the time out to quarterly and eventually biannual or annual reviews.</p><p>Importantly, because your trading plan is a living document, do not stress if you have trouble putting one together at this point in time. Just do the best you can, and it will improve as you develop as a trader, provided you are disciplined with your reviews.</p><h3 id="detailed-vs-simple" tabindex="-1">Detailed vs Simple <a class="header-anchor" href="#detailed-vs-simple" aria-label="Permalink to &quot;Detailed vs Simple&quot;">​</a></h3><p>There is often much discussion and debate about whether a trading plan should be detailed or quite simple. There are pros and cons for both.</p><p>I’ve seen incredibly detailed plans comprising 50+ pages; and others comprising only a paragraph or two.</p><p>Whatever works for you is best.</p><p>However, I will suggest that during your development phase a single page plan IS insufficient. When you have a dozen years experience behind you then you may not need every aspect of your business documented. Most detail will then be internalized and your plan, while only one page on paper, is actually quite detailed when considering all your trading skills, knowledge, attitude and habits. Until you reach this stage, you need clear guidance. And the only way to do that is to make as detailed a plan as possible.</p><p>The problem most people find though is that they create a detailed plan but never refer to it – it’s too complex and unwieldy to refer to in the heat of the daily trading battle.</p><p>As such I recommend the following:</p><ul><li>A detailed trading plan – produced, not with the intent of being referred to day to day, but because of the clarity that the process of producing this document will provide to you with regards the operation of your trading business.</li><li>A separation of the day to day procedures, into it’s own document – The Procedures Manual – which we’ll create in <a href="/sk/trading-with-pav/procedures-manual/">article 81</a></li></ul><h3 id="the-trading-plan-template" tabindex="-1">The Trading Plan Template <a class="header-anchor" href="#the-trading-plan-template" aria-label="Permalink to &quot;The Trading Plan Template&quot;">​</a></h3><p>Next article provides the template which I currently use and article after that contains explanatory notes.</p><h2 id="comments" tabindex="-1">Comments <a class="header-anchor" href="#comments" aria-label="Permalink to &quot;Comments&quot;">​</a></h2>',27)),t(i,null,{default:s(()=>[t(n)]),_:1})])}const w=o(h,[["render",p]]);export{v as __pageData,w as default};
